preConditionHook:
// EL: priorHigh = Highest(high[1], rangeBars) -- the window ENDS ONE BAR BACK,
// bars 1..rangeBars, so the signal bar cannot define the level it is measured
// against. Passing the shifted series high[1] makes Extremes scan Price[0] ..
// Price[rangeBars - 1], i.e. high[1] .. high[rangeBars].
// Extremes is EL SOURCE: seeded on the first bar of the window, scanning the
// rest with a strict comparison so a tie keeps the earliest bar, and its
// comparisons carry the relational tolerance -- hence el_gt/el_lt, not >/<.
// minRoomPoints is in PRICE UNITS: the source counts ticks and tick size needs
// MinMove / PriceScale, both UNKNOWN in EL_FEATURES.md.
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)rangeBars; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
